package com.abhishek.hotelbooking.controller; import com.abhishek.hotelbooking.dto.booking.BookingResponse; import com.abhishek.hotelbooking.dto.payment.PaymentUpdateRequest; import com.abhishek.hotelbooking.service.impl.BookingService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController { private final BookingService service; public AdminController(BookingService service){this.service=service;} @GetMapping("/bookings") public List<BookingResponse> all(){return service.all();} @PutMapping("/bookings/{id}/payment") public BookingResponse payment(@PathVariable Long id,@Valid @RequestBody PaymentUpdateRequest r){return service.payment(id,r.status());} }